/* Extended product walkthrough. Local sample state, no external requests. */
(()=>{
const fresh=()=>({role:'Administrator',members:[{name:'Alex Shah',email:'alex@example.com',role:'Administrator',account:'All accounts'}],requests:[],groups:{},health:{},schedules:[],settings:{name:'Northstar Collective',threshold:50000},uploads:[]});
let state=fresh(),uploads=[],period='11–17 Sep 2026';try{const s=JSON.parse(sessionStorage.getItem('ad-operations'));if(s&&Array.isArray(s.members)&&Array.isArray(s.requests)&&s.settings)state={...state,...s,uploads:[]}}catch(e){}
const persist=()=>{try{sessionStorage.setItem('ad-operations',JSON.stringify(state))}catch(e){toast('Browser storage unavailable. Changes last until reload.')}};
const btn=(a,t,id='')=>`<button data-op="${a}" data-id="${id}">${t}</button>`;
const note='<p class="note">Demo workspace. Changes stay in this browser tab; no emails, platform updates or background jobs are sent.</p>';
const panel=(title,body)=>`<section class="panel op-panel"><div class="panel-head"><h2>${title}</h2></div><div class="op-body">${body}</div></section>`;
const input=(label,name,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" required maxlength="120"></label>`;
const options=(values,current)=>values.map(v=>`<option ${current===v?'selected':''}>${esc(v)}</option>`).join('');
const form=(kind,body,id='')=>`<form data-op-form="${kind}" data-id="${id}" class="op-form">${body}<p class="op-error" role="alert"></p><div class="modal-actions"><button type="button" data-action="close">Cancel</button><button class="primary">Save</button></div></form>`;
const allowed=(kind)=>state.role==='Administrator'||(kind==='approve'&&state.role==='Approver')||(kind==='edit'&&state.role==='Campaign manager');
for(const [key,title] of Object.entries({team:'Team & access',approvals:'Budget approvals',settings:'Settings'})){routes[key]=title;$('nav').insertAdjacentHTML('beforeend',`<a href="#${key}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 9h8M8 12h8M8 15h5"/></svg>${title}</a>`)}
views.team=()=>head('Team & access','Manage sample members and preview role restrictions.',btn('member','Add sample member'))+panel('Preview permissions',`<label>Acting role<select id="acting-role">${options(['Administrator','Campaign manager','Approver','Viewer'],state.role)}</select></label><p class="note">Administrator: all actions. Manager: prepare changes. Approver: approve changes. Viewer: read and export. This switch is a demo control, not authentication.</p>`)+panel('Members',`<div class="table-wrap"><table><thead><tr><th>Name</th><th>Role</th><th>Account access</th><th></th></tr></thead><tbody>${state.members.map((m,i)=>`<tr><td>${esc(m.name)}<small class="op-small">${esc(m.email)}</small></td><td>${esc(m.role)}</td><td>${esc(m.account)}</td><td>${btn('member','Edit',i)}</td></tr>`).join('')}</tbody></table></div>`)+note;
views.approvals=()=>head('Budget approvals','Review proposed daily budgets before applying them to the demo.')+panel('Pending requests',state.requests.some(r=>r.status==='Pending')?state.requests.filter(r=>r.status==='Pending').map(r=>`<div class="op-row"><div><strong>${esc(campaigns.find(c=>c.id===r.campaign)?.name||'Campaign')}</strong><p>${money(r.before)} to ${money(r.amount)} per day · requested as ${esc(r.by)}</p></div><div>${btn('approve','Approve',r.id)} ${btn('reject','Reject',r.id)}</div></div>`).join(''):'<p>No pending budget requests. Open a campaign and save a new daily budget to create one.</p>')+panel('Spend alerts',`<p>Sample period threshold: <strong>${money(state.settings.threshold)}</strong></p>${campaigns.filter(c=>c.spend>=state.settings.threshold).map(c=>`<p class="op-alert">${esc(c.name)} · ${money(c.spend)} spent in the sample period</p>`).join('')||'<p>No campaigns have reached the threshold.</p>'}<p class="note">Based on historical sample spend. This is an alert, not an automatic spending cap.</p>`)+panel('Decision history',state.requests.filter(r=>r.status!=='Pending').map(r=>`<p>${esc(campaigns.find(c=>c.id===r.campaign)?.name||'Campaign')} · ${money(r.amount)} · ${esc(r.status)}</p>`).join('')||'<p>No decisions yet.</p>')+note;
views.settings=()=>head('Settings','Workspace preferences for this demonstration.')+panel('Workspace',`<form class="op-form" data-op-form="settings">${input('Workspace name','name',state.settings.name)}<label>Spend alert threshold (INR)<input name="threshold" type="number" min="100" max="100000000" value="${state.settings.threshold}" required></label><label>Reporting time zone<select disabled><option>Asia/Kolkata</option></select></label><label>Reporting currency<select disabled><option>INR</option></select></label><p class="note">Currency and time zone are fixed for this sample dataset.</p><button class="primary">Save settings</button></form>`)+note;
const oldAssets=views.assets;
views.assets=()=>head('Creative library','Sample concepts and local media previews.',btn('upload','Upload creative'))+panel('Uploaded files',uploads.length?`<div class="cards">${uploads.map((u,i)=>`<article class="asset-card">${u.type.startsWith('image/')?`<img class="op-media" src="${u.url}" alt="${esc(u.name)}">`:`<video class="op-media" src="${u.url}" controls preload="metadata"></video>`}<div class="asset-body"><h3>${esc(u.name)}</h3><p>${u.width} × ${u.height} · ${(u.size/1024/1024).toFixed(1)} MB</p>${btn('attach','Assign to ad',i)} ${btn('remove-upload','Remove',i)}</div></article>`).join('')}</div>`:'<p>No uploads yet. Add a JPG, PNG, WebP or MP4 file up to 20 MB. Files remain on this device and clear on reload.</p>')+oldAssets().replace(/^[\s\S]*?<div class="cards">/,'<div class="cards">').replace('Typography-based sample concepts, not uploaded production files. Asset upload, format validation and platform delivery are represented by the proposed production workflow.','Sample concepts are separate from uploaded local media. Platform delivery remains simulated.')+note;
const oldDetail=detail;
detail=function(id){oldDetail(id);$('#dialog .modal-body').insertAdjacentHTML('afterbegin',`<div class="op-toolbar">${btn('structure','Ad groups & ads',id)}</div>`);$('#budget-form button').textContent='Request change';};
function structure(id){const c=campaigns.find(c=>c.id===id);if(!c)return;const groups=state.groups[id]||[];close();modal('Ad groups & ads',esc(c.name)+' · '+esc(c.platform),`<p class="note">Simplified structure: campaign → ${c.platform==='Meta'?'ad set':'ad group'} → ad. No real ads are published.</p>${btn('group','Add '+(c.platform==='Meta'?'ad set':'ad group'),id)}${groups.map((g,i)=>panel(esc(g.name),`<p>${esc(g.target)}</p>${btn('edit-group','Edit group',id+':'+i)} ${btn('ad','Add ad',id+':'+i)}${g.ads.map((a,j)=>`<div class="op-row"><div><strong>${esc(a.name)}</strong><p>${esc(a.copy)}</p><small>${esc(a.creative||'Sample creative')} · ${esc(a.status)}</small></div>${btn('edit-ad','Edit ad',id+':'+i+':'+j)} ${btn('toggle-ad',({Draft:'Submit for review','In review':'Approve (demo)',Active:'Pause',Paused:'Resume'})[a.status],id+':'+i+':'+j)}</div>`).join('')||'<p>No ads in this group yet.</p>'}`)).join('')}`)}
const oldAccounts=views.accounts;
views.accounts=()=>oldAccounts()+panel('Connection health',accountKeys().map((k,i)=>{const h=state.health[k]||{status:'Ready',time:'Not synced this session'};return `<div class="op-row"><div><strong>${esc(k)}</strong><p>${esc(h.status)} · ${esc(h.time)}</p></div><div>${btn('sync','Sync sample data',i)} ${btn('expire','Test expired access',i)} ${btn('sync-fail','Test sync failure',i)}</div></div>`}).join(''))+note;
const oldReports=views.reports;
views.reports=()=>`<div class="op-toolbar"><label>Sample reporting period<select id="report-period">${options(['11–17 Sep 2026','11–13 Sep 2026','14–17 Sep 2026'],period)}</select></label>${btn('schedule','Schedule report')}</div>`+oldReports()+panel('Scheduled reports',state.schedules.map((s,i)=>`<div class="op-row"><div><strong>${esc(s.name)}</strong><p>${esc(s.frequency)} · ${esc(s.email)} · ${esc(s.client)}</p><small>${s.paused?'Paused':'Demo schedule saved — no emails sent'}</small></div>${btn('toggle-schedule',s.paused?'Resume':'Pause',i)}</div>`).join('')||'<p>No report schedules.</p>')+note;
// All report views and exports use the same deterministic sample-day weights.

// scoped is a const in the base demo; use a temporary dataset during report rendering/export.
const reportView=views.reports;
function withPeriod(fn){const all=campaigns;if(currentRoute==='reports'&&period!=='11–17 Sep 2026'){const ratio=period==='11–13 Sep 2026'?.339:.661;campaigns=all.map(c=>({...c,spend:Math.round(c.spend*ratio),revenue:Math.round(c.revenue*ratio),conversions:Math.round(c.conversions*ratio)}))}try{return fn()}finally{campaigns=all}}
views.reports=()=>withPeriod(()=>reportView().replaceAll('11–17 Sep 2026 · INR',period+' · INR').replaceAll('11–17 Sep 2026 <span>·</span> INR',period+' <span>·</span> INR').replaceAll('11–17 September 2026',period));
const previousExport=exportCsv;exportCsv=function(type){if(currentRoute!=='reports')return previousExport(type);withPeriod(()=>{const rows=[['Campaign','Platform','Period','Spend INR','Revenue INR','Conversions','Data'],...scoped().map(c=>[c.name,c.platform,period,c.spend,c.revenue,c.conversions,'Illustrative'])];if(type==='accounts'||type==='budgets')return previousExport(type);const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[\s]*[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='Sample_performance.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Selected period exported.')})};
function openForm(title,kind,body,id=''){close();modal(title,'Local demonstration only',form(kind,body,id))}
window.addEventListener('click',e=>{
const b=e.target.closest('[data-op]'),a=e.target.closest('[data-action]');if(e.target.closest('[data-connect]')&&!allowed('admin')){e.stopImmediatePropagation();toast('Only the administrator can change account connections.');return}
if(a?.dataset.action==='confirm-reset'&&allowed('admin')){uploads.forEach(u=>URL.revokeObjectURL(u.url));uploads=[];state=fresh();period='11–17 Sep 2026';$('.client-brand>div').innerHTML=esc(state.settings.name)+'<small>Sample agency workspace</small>';persist()}
const writes=['create','use-asset','targeting','status','route','connect','connect-info','account-route','confirm-reset'];
if(a&&writes.includes(a.dataset.action)&&!allowed(a.dataset.action==='confirm-reset'?'admin':a.dataset.action==='status'&&campaigns.find(c=>c.id===Number(a.dataset.id))?.status==='In review'?'approve':'edit')){e.stopImmediatePropagation();toast('This action is unavailable for the preview role. Change it in Team & access.');return}
if(e.target.closest('[data-premium="duplicate"]')&&!allowed('edit')){e.stopImmediatePropagation();toast('Your preview role cannot create drafts.');return}if(!b)return;const act=b.dataset.op,id=b.dataset.id;
const read=['structure'];if(act==='toggle-ad'){const [c,g,i]=id.split(':');if(state.groups[c][g].ads[i].status==='In review'&&allowed('approve')){state.groups[c][g].ads[i].status='Active';persist();structure(Number(c));return}}if(!read.includes(act)&&!allowed(['approve','reject'].includes(act)?'approve':['member','schedule','toggle-schedule','expire','sync-fail','sync'].includes(act)?'admin':'edit')){toast('This action is unavailable for the preview role.');return}
if(act==='member'){const m=id!==''?state.members[Number(id)]:{};openForm('Sample team member','member',input('Name','name',m.name||'')+input('Email — no invitation sent','email',m.email||'','email')+`<label>Role<select name="role">${options(['Administrator','Campaign manager','Approver','Viewer'],m.role)}</select></label><label>Account access<select name="account">${options(['All accounts',...accountKeys()],m.account)}</select></label><p class="note">Account assignments are stored for the walkthrough. They do not filter the separate demo sandbox.</p>`,id)}
if(act==='structure')structure(Number(id));
if(act==='group')openForm('Add ad group / ad set','group',input('Name','name')+input('Audience or keyword brief','target'),id);
if(act==='edit-group'){const [c,g]=id.split(':');const group=state.groups[c][g];openForm('Edit group','edit-group',input('Name','name',group.name)+input('Audience or keyword brief','target',group.target),id)}
if(act==='edit-ad'){const [c,g,a]=id.split(':');const ad=state.groups[c][g].ads[a];openForm('Edit ad','edit-ad',input('Ad name','name',ad.name)+input('Ad text','copy',ad.copy),id)}
if(act==='ad')openForm('Add ad','ad',input('Ad name','name')+input('Ad text','copy')+`<label>Creative<select name="creative">${options([...assets.map(a=>a.title),...uploads.map(u=>u.name)])}</select></label>`,id);
if(act==='toggle-ad'){const [c,g,i]=id.split(':');const ad=state.groups[c][g].ads[i];if(ad.status==='In review'&&!allowed('approve'))return toast('An approver must approve this ad.');ad.status=({Draft:'In review','In review':'Active',Active:'Paused',Paused:'Active'})[ad.status];persist();structure(Number(c))}
if(act==='upload')openForm('Upload creative','upload',`<label>Media file<input name="file" type="file" accept="image/jpeg,image/png,image/webp,video/mp4" required></label><p class="note">JPG, PNG, WebP or MP4 · up to 20 MB. Basic format and media checks only; platform-specific validation is not performed.</p>`);
if(act==='remove-upload'){URL.revokeObjectURL(uploads[Number(id)].url);uploads.splice(Number(id),1);render()}
if(act==='attach'){const choices=Object.entries(state.groups).flatMap(([c,gs])=>gs.flatMap((g,i)=>g.ads.map((a,j)=>({id:`${c}:${i}:${j}`,name:campaigns.find(x=>x.id===Number(c))?.name+' / '+g.name+' / '+a.name}))));if(!choices.length)return toast('Create an ad in Campaigns → Open → Ad groups & ads first.');openForm('Assign creative','attach',`<label>Ad<select name="ad">${choices.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label>`,id)}
if(['approve','reject'].includes(act)){const r=state.requests.find(x=>x.id===Number(id));if(!r||r.status!=='Pending')return;if(act==='approve'&&state.role===r.by)return toast('Switch to another approver role to approve this request.');const c=campaigns.find(c=>c.id===r.campaign);if(!c)return;if(act==='approve'){if(c.budget!==r.before)return toast('Budget changed. Reject this request and submit a new one.');c.budget=r.amount;save()}r.status=act==='approve'?'Approved':'Rejected';record(`${c.name} · budget request ${r.status.toLowerCase()}`);persist();render()}
if(['sync','expire','sync-fail'].includes(act)){const k=accountKeys()[Number(id)];if(act==='expire'){state.health[k]={status:'Access expired — reconnect account',time:'Sync blocked'};delete demoConnections[k];persistConnections()}else if(act==='sync-fail')state.health[k]={status:'Sync failed — retry available',time:'Last successful data retained'};else{if(state.health[k]?.status.startsWith('Access expired')&&!demoConnections[k])return toast('Reconnect this sample account before syncing.');state.health[k]={status:'Ready',time:'Sample sync: '+new Date().toLocaleTimeString()};record(k+' · sample sync completed')}persist();render()}
if(act==='schedule')openForm('Schedule report','schedule',input('Report name','name','Weekly performance')+input('Recipient — no emails sent','email','','email')+`<label>Frequency<select name="frequency">${options(['Daily at 09:00','Monday at 09:00','First of month at 09:00'])}</select></label><p class="note">Asia/Kolkata · Portfolio: ${esc(selectedClient)}. This saves a sample schedule only.</p>`);
if(act==='toggle-schedule'){state.schedules[Number(id)].paused=!state.schedules[Number(id)].paused;persist();render()}
},true);
document.addEventListener('change',e=>{if(e.target.id==='acting-role'){state.role=e.target.value;persist();render();toast('Previewing '+state.role+' permissions.')}if(e.target.id==='report-period'){period=e.target.value;render()}});
window.addEventListener('submit',async e=>{
const f=e.target;
if(['wizard-form','create-form','targeting-form','route-form'].includes(f.id)&&!allowed('edit')){e.preventDefault();e.stopImmediatePropagation();toast('Your preview role cannot save changes.');return}
if(f.id==='budget-form'){e.preventDefault();e.stopImmediatePropagation();if(!allowed('edit'))return toast('Only an administrator or manager can request budget changes.');const c=campaigns.find(c=>c.id===Number(f.dataset.id)),amount=Number(new FormData(f).get('budget'));if(amount===c.budget)return toast('Enter a different budget.');if(state.requests.some(r=>r.campaign===c.id&&r.status==='Pending'))return toast('Review the existing pending request first.');state.requests.push({id:Date.now(),campaign:c.id,before:c.budget,amount,status:'Pending',by:state.role});persist();close();go('approvals');toast('Budget change submitted. Current budget is unchanged.');return}
const kind=f.dataset.opForm;if(!kind)return;e.preventDefault();const d=Object.fromEntries(new FormData(f));const id=f.dataset.id;
if(!allowed(['member','settings','schedule'].includes(kind)?'admin':'edit'))return toast('Your preview role cannot save this form.');for(const k of ['name','copy','target'])if(k in d&&!String(d[k]).trim()){f.querySelector('.op-error')?.replaceChildren(document.createTextNode('Enter a value; spaces alone are not valid.'));return}
if(kind==='member'){if(state.members.some((m,i)=>m.email.toLowerCase()===d.email.toLowerCase()&&String(i)!==id))return toast('This email is already in the team.');if(id==='')state.members.push(d);else state.members[Number(id)]=d}
if(kind==='settings'){state.settings={name:d.name.trim(),threshold:Number(d.threshold)};persist();$('.client-brand>div').innerHTML=esc(state.settings.name)+'<small>Sample agency workspace</small>';toast('Workspace settings saved.');render();return}
if(kind==='group'){(state.groups[id]??=[]).push({name:d.name.trim(),target:d.target.trim(),ads:[]});persist();structure(Number(id));return}
if(kind==='edit-group'){const [c,g]=id.split(':');Object.assign(state.groups[c][g],d);persist();structure(Number(c));return}
if(kind==='edit-ad'){const [c,g,a]=id.split(':');Object.assign(state.groups[c][g].ads[a],d,{status:'Draft'});persist();structure(Number(c));return}
if(kind==='ad'){const [c,g]=id.split(':');state.groups[c][g].ads.push({...d,status:'Draft'});persist();structure(Number(c));return}
if(kind==='attach'){const [c,g,a]=d.ad.split(':');state.groups[c][g].ads[a].creative=uploads[Number(id)].name;state.groups[c][g].ads[a].status='Draft'}
if(kind==='schedule')state.schedules.push({...d,client:selectedClient,paused:false});
if(kind==='upload'){const file=d.file;if(!['image/jpeg','image/png','image/webp','video/mp4'].includes(file.type)||file.size>20*1024*1024||!file.size)return toast('Choose a supported non-empty file up to 20 MB.');if(uploads.length>=12)return toast('Demo limit: 12 uploads. Remove a file first.');const url=URL.createObjectURL(file),media=file.type.startsWith('image/')?new Image():document.createElement('video');try{await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error()),8000);media.onload=media.onloadedmetadata=()=>{clearTimeout(timer);resolve()};media.onerror=()=>{clearTimeout(timer);reject(Error())};media.src=url});uploads.push({name:file.name,type:file.type,size:file.size,url,width:media.naturalWidth||media.videoWidth,height:media.naturalHeight||media.videoHeight})}catch(err){URL.revokeObjectURL(url);return toast('This media file could not be read.')}if(!f.isConnected)return}
persist();record(kind+' · sample configuration saved');close();render();toast('Saved in the demo.');
},true);
$('.client-brand>div').innerHTML=esc(state.settings.name)+'<small>Sample agency workspace</small>';
render();
})();
